const NOVA_JQL = "project = RH AND assignee = currentUser() AND statusCategory != Done ORDER BY updated ASC";

export const searchAll = async (jql: string, fields = ["summary", "status", "assignee"]) => {
  const issues: JiraIssue[] = [];
  let nextPageToken: string | undefined;
  do {
    const page = await jiraFetch<SearchPage>("/rest/api/3/search/jql", {
      method: "POST",
      body: JSON.stringify({ jql, fields, maxResults: 100, nextPageToken }),
    });
    issues.push(...(page?.issues ?? []));
    nextPageToken = page?.nextPageToken;
  } while (nextPageToken);
  return issues;
};

export async function requesterOf(key: string): Promise<string | undefined> {
  const fromSlack = await jira.issueProperty<string>(key, "nova.requester");
  if (fromSlack) return fromSlack;
  const history = await jira.changelog(key); // oldest first
  const toNova = history.filter((c) => c.items.some((i) => i.field === "assignee" && i.to === jira.me));
  return toNova.at(-1)?.author.accountId;
}

export const jiraFetch = async <T>(path: string, init: RequestInit = {}): Promise<T | undefined> => {
  for (let attempt = 1; ; attempt++) {
    const res = await fetch(`${BASE}${path}`, { ...init, headers: { Authorization: AUTH,
      Accept: "application/json", "Content-Type": "application/json" } });
    if (res.status === 429 && attempt < 5) {
      const seconds = Number(res.headers.get("Retry-After") ?? 5);
      await new Promise((r) => setTimeout(r, seconds * 1000));
      continue;
    }
    if (res.status === 404) return undefined;
    if (!res.ok) throw new Error(`Jira ${init.method ?? "GET"} ${path}: ${res.status}`);
    return res.status === 204 ? undefined : ((await res.json()) as T);
  }
};

