const BASE = `http://localhost:${process.env.JIRA_PORT ?? 4000}`;
const JQL = "project = RH AND assignee = currentUser() AND statusCategory != Done ORDER BY updated ASC";

const jiraFetch = async (path, init = {}) => {
  for (;;) {
    const res = await fetch(BASE + path, { ...init, headers: { "Content-Type": "application/json", Accept: "application/json" } });
    if (res.status === 429) {
      const seconds = Number(res.headers.get("Retry-After") ?? 5);
      console.log(`Jira said 429, waiting ${seconds} s`);
      await new Promise((r) => setTimeout(r, seconds * 1000));
      continue;
    }
    if (res.status === 404) return undefined;
    if (!res.ok) throw new Error(`Jira ${path}: ${res.status}`);
    return res.json();
  }
};

const searchAll = async (jql) => {
